// Lee el data_url crudo desde el input (puede venir como /rails/active_storage... o con algún prefijo inválido)
const rawUrl =$input.first().json.propertyName[0];

// Busca la parte desde /rails/active_storage...
const index = rawUrl.indexOf('/rails/active_storage');
const path = rawUrl.slice(index);

// Arma la URL absoluta con el prefijo correcto
const prefijo = 'https://dfchatwoot.sistemadistribuidorafenix.com/';
const finalUrl = prefijo + path;

// Devuelve la nueva URL en el output para usar en el siguiente nodo
return [
  {
    json: {
      audioUrl: finalUrl
    }
  }
];

// 1. Obtener los datos de n8n de forma segura
const itemData = items[0].json;

// Función helper: limpia bloques de markdown (```json ... ``` o ``` ... ```)
// antes de intentar parsear como JSON.
function limpiarYParsear(raw) {
  if (typeof raw !== 'string') return raw;

  let limpio = raw.trim();

  // Si viene envuelto en bloque de código markdown, lo removemos
  if (limpio.startsWith('```')) {
    limpio = limpio
      .replace(/^```[a-zA-Z]*\n?/, '') // saca la apertura ```json o ```
      .replace(/```$/, '')             // saca el cierre ```
      .trim();
  }

  return JSON.parse(limpio);
}

try {
  let content;

  // 2. Extraer el contenido del mensaje según la estructura del input.txt
  if (itemData.choices && itemData.choices[0] && itemData.choices[0].message) {
    const rawContent = itemData.choices[0].message.content;
    content = limpiarYParsear(rawContent);
  } else if (itemData.data) {
    // Por si viene envuelto en una propiedad 'data'
    const rawData = typeof itemData.data === 'string' ? JSON.parse(itemData.data) : itemData.data;
    const rawContent = rawData.choices[0].message.content;
    content = limpiarYParsear(rawContent);
  } else {
    throw new Error("No se encontró la estructura esperada de la IA (choices.message.content).");
  }

  // 3. Desestructurar los datos validados
  const { proveedor, factura, productos, totales } = content;

  // 4. Mapear y normalizar cada producto al formato de salida de n8n
  return productos.map(p => ({
    json: {
      proveedor_nombre:          proveedor?.nombre || null,
      proveedor_nombre_fantasia: proveedor?.proveedor_nombre_fantasia || null,
      proveedor_cuit:            proveedor?.cuit_rut_nit || null,
      factura_numero:            factura?.numero || null,
      factura_fecha:             factura?.fecha || null,
      factura_tipo:              factura?.tipo || null,
      producto_codigo:           p.codigo || null,
      producto_descripcion:      p.descripcion || null,
      cantidad:                  Number(p.cantidad) || 0,
      precio_unitario:           Number(p.precio_unitario) || 0,
      descuento:                 Number(p.descuento) || 0,
      precio_total:              Number(p.precio_total) || 0,
      subtotal_factura:          totales?.subtotal || 0,
      impuestos_factura:         totales?.impuestos || 0,
      total_factura:             totales?.total || 0
    }
  }));

} catch (error) {
  // En caso de error, devuelve un objeto con el detalle en lugar de romper el flujo
  return [{
    json: {
      error: true,
      message: error.message
    }
  }];
}

const item = items[0].json;

const textContent = item.output[0].content[0].text;
const content = JSON.parse(textContent);

const { proveedor, factura, productos, totales } = content;

// El LLM a veces devuelve nombre_fantasia dentro de proveedor
// y otras veces como proveedor_nombre_fantasia en el mismo nivel.
// Este fallback cubre ambos casos.
const nombreFantasia = proveedor.nombre_fantasia 
  ?? proveedor.proveedor_nombre_fantasia 
  ?? '';

return productos.map(p => ({
  json: {
    proveedor_nombre:          proveedor.nombre,
    proveedor_nombre_fantasia: nombreFantasia,
    proveedor_cuit:            proveedor.cuit_rut_nit,
    factura_numero:            factura.numero,
    factura_fecha:             factura.fecha,
    factura_tipo:              factura.tipo,
    producto_codigo:           p.codigo,
    producto_descripcion:      p.descripcion,
    cantidad:                  p.cantidad,
    precio_unitario:           p.precio_unitario,
    descuento:                 p.descuento,
    precio_total:              p.precio_total,
    subtotal_factura:          totales.subtotal,
    impuestos_factura:         totales.impuestos,
    total_factura:             totales.total
  }
}));
